urlset:
  https://yusuke8696.github.io/
{%- assign documents = site.static_files | concat: site.pages | sort: 'path' -%}
{%- for document in documents -%}
  {%- assign prefix = document.path | slice: 0, 9 -%}
  {%- assign extension = document.path | split: '.' | last -%}
  {%- if prefix == 'articles/' and extension == 'html' and document.sitemap != false and document.draft != true %}
  {{ document.path | prepend: 'https://yusuke8696.github.io/' | xml_escape }}
  {%- endif -%}
{%- endfor %}
